<script>
(function() {
  // --- Texture Generation (Procedural Bump Maps) ---
  function createTex(drawFn) {
    const c = document.createElement('canvas');
    c.width = 512; c.height = 512;
    const x = c.getContext('2d');
    x.fillStyle = 'black';
    x.fillRect(0, 0, 512, 512);
    x.filter = 'blur(4px)';
    x.fillStyle = 'white';
    x.strokeStyle = 'white';
    drawFn(x);
    return x.getImageData(0, 0, 512, 512).data;
  }

  const frontTex = createTex((x) => {
    x.lineWidth = 16;
    x.beginPath(); x.arc(256, 256, 230, 0, Math.PI*2); x.stroke();
    x.beginPath(); x.arc(256, 256, 200, 0, Math.PI*2); x.stroke();
    x.textAlign = 'center'; x.textBaseline = 'middle';
    x.font = 'bold 64px sans-serif';
    x.fillText('WASTED', 256, 200);
    x.font = 'bold 40px sans-serif';
    x.fillText('TOKEN MINT', 256, 310);
    x.beginPath(); x.arc(256, 256, 45, 0, Math.PI*2); x.fill();
    x.fillStyle = 'black';
    x.beginPath(); x.arc(256, 256, 25, 0, Math.PI*2); x.fill();
    x.fillStyle = 'white';
    for(let i=0; i<5; i++) {
      let a = i * Math.PI*2/5 - Math.PI/2;
      let a2 = a + Math.PI/5;
      x.beginPath();
      x.moveTo(256 + Math.cos(a)*15, 256 + Math.sin(a)*15);
      x.lineTo(256 + Math.cos(a2)*8, 256 + Math.sin(a2)*8);
      x.lineTo(256 + Math.cos(a+Math.PI*2/5)*15, 256 + Math.sin(a+Math.PI*2/5)*15);
      x.fill();
    }
  });

  const backTex = createTex((x) => {
    x.lineWidth = 16;
    x.beginPath(); x.arc(256, 256, 230, 0, Math.PI*2); x.stroke();
    x.beginPath(); x.arc(256, 256, 200, 0, Math.PI*2); x.stroke();
    x.textAlign = 'center'; x.textBaseline = 'middle';
    x.font = 'bold 80px sans-serif';
    x.fillText('10,000', 256, 230);
    x.font = 'bold 50px sans-serif';
    x.fillText('TOKENS', 256, 320);
  });

  function sampleTex(texData, u, v) {
    u = Math.max(0, Math.min(0.999, u));
    v = Math.max(0, Math.min(0.999, v));
    const px = Math.floor(u * 512);
    const py = Math.floor(v * 512);
    const idx = (py * 512 + px) * 4;
    return texData[idx] / 255.0;
  }

  // --- Materials ---
  const MATERIALS = {
    bronze: { albedo: [0.72, 0.45, 0.20], spec: [1.0, 0.8, 0.5], shininess: 32 },
    silver: { albedo: [0.85, 0.85, 0.90], spec: [1.0, 1.0, 1.0], shininess: 48 },
    gold:   { albedo: [0.95, 0.75, 0.25], spec: [1.0, 0.9, 0.5], shininess: 64 },
    black:  { albedo: [0.15, 0.15, 0.18], spec: [0.8, 0.8, 0.9], shininess: 96 }
  };

  // --- Software 3D Raycaster for Canvas ---
  class CoinRenderer {
    constructor(canvas, material, bgColor, isHero) {
      this.canvas = canvas;
      this.ctx = canvas.getContext('2d', { willReadFrequently: true });
      this.width = canvas.width;
      this.height = canvas.height;
      this.material = material;
      this.bgColor = bgColor;
      this.imgData = this.ctx.createImageData(this.width, this.height);
      this.R = isHero ? 0.85 : 0.75;
      this.H = isHero ? 0.06 : 0.05;
    }

    render(t) {
      const data = this.imgData.data;
      const R = this.R, H = this.H;
      const A = t * Math.PI * 2.0;
      const B = t * Math.PI * 2.0;
      const camZ = -2.5;

      const cA = Math.cos(A), sA = Math.sin(A);
      const cB = Math.cos(B), sB = Math.sin(B);

      // Fixed world light
      let Lx = 0.5, Ly = 0.8, Lz = 1.0;
      const Llen = Math.sqrt(Lx*Lx + Ly*Ly + Lz*Lz);
      Lx /= Llen; Ly /= Llen; Lz /= Llen;
      const L_world = [Lx, Ly, Lz];

      for (let py = 0; py < this.height; py++) {
        for (let px = 0; px < this.width; px++) {
          const nx = (px - this.width/2) / (this.width/2);
          const ny = (this.height/2 - py) / (this.height/2);

          let dx = nx, dy = ny, dz = -camZ;
          const dlen = Math.sqrt(dx*dx + dy*dy + dz*dz);
          dx /= dlen; dy /= dlen; dz /= dlen;

          const ox = 0, oy = 0, oz = camZ;

          // Transform ray to local space
          const ox1 = ox * cA - oz * sA;
          const oz1 = ox * sA + oz * cA;
          const oy1 = oy;
          const ox2 = ox1;
          const oy2 = oy1 * cB - oz1 * sB;
          const oz2 = oy1 * sB + oz1 * cB;

          const dx1 = dx * cA - dz * sA;
          const dz1 = dx * sA + dz * cA;
          const dy1 = dy;
          const dx2 = dx1;
          const dy2 = dy1 * cB - dz1 * sB;
          const dz2 = dy1 * sB + dz1 * cB;

          let hit = false, hitT = Infinity;
          let hitNormal = [0,0,0], hitU = 0, hitV = 0;
          let isCap = false, isFront = false;

          // Cylinder side
          const a = dx2*dx2 + dy2*dy2;
          const b = 2.0 * (ox2*dx2 + oy2*dy2);
          const c = ox2*ox2 + oy2*oy2 - R*R;
          if (a > 1e-6) {
            const disc = b*b - 4*a*c;
            if (disc >= 0) {
              const tSide = (-b - Math.sqrt(disc)) / (2*a);
              if (tSide > 0) {
                const hx = ox2 + tSide*dx2;
                const hy = oy2 + tSide*dy2;
                const hz = oz2 + tSide*dz2;
                if (hz >= -H && hz <= H) {
                  hit = true; hitT = tSide; hitNormal = [hx/R, hy/R, 0]; isCap = false;
                }
              }
            }
          }

          // Caps
          if (dz2 > 1e-6 || dz2 < -1e-6) {
            const tFront = (H - oz2) / dz2;
            if (tFront > 0 && tFront < hitT) {
              const hx = ox2 + tFront*dx2;
              const hy = oy2 + tFront*dy2;
              if (hx*hx + hy*hy <= R*R) {
                hit = true; hitT = tFront; hitNormal = [0,0,1];
                isCap = true; isFront = true;
                hitU = hx/R * 0.5 + 0.5; hitV = 1.0 - (hy/R * 0.5 + 0.5);
              }
            }
            const tBack = (-H - oz2) / dz2;
            if (tBack > 0 && tBack < hitT) {
              const hx = ox2 + tBack*dx2;
              const hy = oy2 + tBack*dy2;
              if (hx*hx + hy*hy <= R*R) {
                hit = true; hitT = tBack; hitNormal = [0,0,-1];
                isCap = true; isFront = false;
                hitU = hx/R * 0.5 + 0.5; hitV = 1.0 - (hy/R * 0.5 + 0.5);
              }
            }
          }

          let r = this.bgColor[0], g = this.bgColor[1], b = this.bgColor[2];

          if (hit) {
            let N = hitNormal;
            let albedo = this.material.albedo;
            const specCol = this.material.spec;
            const shininess = this.material.shininess;

            if (isCap) {
              const tex = isFront ? frontTex : backTex;
              const h0 = sampleTex(tex, hitU, hitV);
              const hx = sampleTex(tex, hitU + 0.005, hitV) - h0;
              const hy = sampleTex(tex, hitU, hitV + 0.005) - h0;

              const shade = 0.6 + 0.4 * h0;
              albedo = [albedo[0]*shade, albedo[1]*shade, albedo[2]*shade];

              N = [ N[0] - hx * 15.0, N[1] - hy * 15.0, N[2] + 0.01 ];
              let nlen = Math.sqrt(N[0]*N[0] + N[1]*N[1] + N[2]*N[2]);
              N = [N[0]/nlen, N[1]/nlen, N[2]/nlen];
              if (!isFront) {
                 N = [N[0], N[1], -Math.abs(N[2])];
                 let n2 = Math.sqrt(N[0]*N[0]+N[1]*N[1]+N[2]*N[2]);
                 N = [N[0]/n2, N[1]/n2, N[2]/n2];
              }
            } else {
              const phi = Math.atan2(hitNormal[1], hitNormal[0]);
              const ridgeDeriv = Math.cos(phi * 120.0) * 120.0 * 0.01;
              N = [
                hitNormal[0] - hitNormal[1] * ridgeDeriv,
                hitNormal[1] + hitNormal[0] * ridgeDeriv,
                0.2
              ];
              const nlen = Math.sqrt(N[0]*N[0] + N[1]*N[1] + N[2]*N[2]);
              N = [N[0]/nlen, N[1]/nlen, N[2]/nlen];
              const ridge = 0.5 + 0.5 * Math.sin(phi * 120.0);
              const shade = 0.7 + 0.3 * ridge;
              albedo = [albedo[0]*shade, albedo[1]*shade, albedo[2]*shade];
            }

            // Transform normal to world space
            const Ny_x = N[0] * cA + N[2] * sA;
            const Ny_y = N[1];
            const Ny_z = -N[0] * sA + N[2] * cA;
            const Nw_x = Ny_x;
            const Nw_y = Ny_y * cB - Ny_z * sB;
            const Nw_z = Ny_y * sB + Ny_z * cB;
            const N_world = [Nw_x, Nw_y, Nw_z];

            // World view vector
            let Vx = -nx, Vy = -ny, Vz = camZ;
            const Vlen = Math.sqrt(Vx*Vx + Vy*Vy + Vz*Vz);
            Vx /= Vlen; Vy /= Vlen; Vz /= Vlen;

            const dotLN = N_world[0]*L_world[0] + N_world[1]*L_world[1] + N_world[2]*L_world[2];
            const diff = Math.max(0, dotLN);

            const Rx = 2*dotLN*N_world[0] - L_world[0];
            const Ry = 2*dotLN*N_world[1] - L_world[1];
            const Rz = 2*dotLN*N_world[2] - L_world[2];
            const spec = Math.pow(Math.max(0, Rx*Vx + Ry*Vy + Rz*Vz), shininess);

            const amb = 0.25;
            r = (albedo[0] * (amb + diff) + specCol[0] * spec) * 255;
            g = (albedo[1] * (amb + diff) + specCol[1] * spec) * 255;
            b = (albedo[2] * (amb + diff) + specCol[2] * spec) * 255;

            const vdn = Math.max(0, Vx*N_world[0] + Vy*N_world[1] + Vz*N_world[2]);
            const fresnel = Math.pow(1.0 - vdn, 3.0);
            r += fresnel * 40; g += fresnel * 40; b += fresnel * 40;
          }

          const idx = (py * this.width + px) * 4;
          data[idx] = Math.min(255, Math.max(0, r));
          data[idx+1] = Math.min(255, Math.max(0, g));
          data[idx+2] = Math.min(255, Math.max(0, b));
          data[idx+3] = 255;
        }
      }
      this.ctx.putImageData(this.imgData, 0, 0);
    }
  }

  // --- Initialization ---
  const heroCanvas = document.getElementById('coin-hero');
  const heroRenderer = new CoinRenderer(heroCanvas, MATERIALS.gold, [20, 20, 25], true);

  const edCanvases = document.querySelectorAll('.edition-canvas');
  const editions = [
    { mat: MATERIALS.bronze, t: 0.12 },
    { mat: MATERIALS.silver, t: 0.12 },
    { mat: MATERIALS.gold,   t: 0.12 },
    { mat: MATERIALS.black,  t: 0.12 }
  ];
  editions.forEach((ed, i) => {
    const canvas = edCanvases[i];
    canvas.width = 150; canvas.height = 150;
    const r = new CoinRenderer(canvas, ed.mat, [30, 30, 35], false);
    r.render(ed.t);
  });

  let isPaused = false;
  let animFrame = null;
  function loop(time) {
    if (isPaused) return;
    const t = (time % 4000) / 4000;
    heroRenderer.render(t);
    animFrame = requestAnimationFrame(loop);
  }
  animFrame = requestAnimationFrame(loop);

  // --- Required API ---
  window.demo = {
    canvas: heroCanvas,
    setTime(t) {
      if (animFrame) cancelAnimationFrame(animFrame);
      isPaused = true;
      heroRenderer.render(t);
    },
    pause() {
      isPaused = true;
      if (animFrame) cancelAnimationFrame(animFrame);
    }
  };
})();
</script>
</body>
</html>
